import EditIcon from "../../asset/icons/edit.svg";
import TrashIcon from "../../asset/icons/trash.svg";

export function todoCheckbox(todo) {
	const checkbox = document.createElement("input");
	checkbox.id = "checkbox";
	checkbox.className = "todo-checkbox";
	checkbox.type = "checkbox";
	checkbox.dataset.statusTodo = todo.status;

	if (todo.status === "done") {
		checkbox.checked = true;
	} else if (todo.status === "wip") {
		checkbox.checked = false;
	}
	return checkbox;
}

function todoTags(todo) {
	const tags = document.createElement("div");
	tags.className = "todo-tags";

	const date = document.createElement("span");
	date.textContent = todo.dueDate;
	date.className = "date";

	const priority = document.createElement("p");
	priority.textContent = todo.priority;
	priority.className = "priority";

	const project = document.createElement("p");
	project.textContent = todo.project.projectName;
	project.dataset.projectId = todo.project.projectId;
	project.dataset.projectName = todo.project.projectName;
	project.className = "project";

	tags.append(date, priority, project);
	return tags;
}

export function todoDetail(todo) {
	// maybe i should add the helper that will check if the todos status is done or wip
	const actionsContainer = document.createElement("div");
	actionsContainer.className = "todo";
	actionsContainer.dataset.id = todo.id;

	const title = document.createElement("p");
	title.textContent = todo.title;
	title.className = "name";

	const description = document.createElement("p");
	description.textContent = todo.description;
	description.className = "description";

	if (todo.status === "done") {
		title.classList.add("checked-todo");
		description.classList.add("checked-todo");
	} else if (todo.status === "wip") {
		title.classList.remove("checked-todo");
		description.classList.remove("checked-todo");
	}

	const tags = todoTags(todo);
	actionsContainer.append(title, description, tags);
	return actionsContainer;
}

export function todoButtons(todo) {
	const buttons = document.createElement("div");
	buttons.className = "btn-group";
	const editBtn = editButton(todo);
	const delBtn = deleteButton(todo);
	buttons.append(editBtn, delBtn);
	return buttons;
}

function editButton(todo) {
	const editBtn = document.createElement("button");
	editBtn.type = "button";
	editBtn.className = "edit-btn";
	editBtn.dataset.id = todo.id;
	editBtn.dataset.projectId = todo.project.projectId;
	const icon = document.createElement("div");
	icon.innerHTML = EditIcon;
	icon.querySelector("svg").classList.add("edit-icon");
	editBtn.append(icon);
	return editBtn;
}

export function deleteButton(todo) {
	const delBtn = document.createElement("button");
	delBtn.type = "button";
	delBtn.className = "del-btn";
	delBtn.dataset.id = todo.id;
	delBtn.dataset.projectId = todo.project.projectId;
	const icon = document.createElement("div");
	icon.innerHTML = TrashIcon;
	icon.querySelector("svg").classList.add("delete-icon");
	delBtn.append(icon);
	return delBtn;
}
